        qsa('[data-h]', m.el).forEach(function (i) { hal[i.dataset.h] = Number(i.value); }); ['ukuran', 'orientasi', 'font'].forEach(function (k) { hal[k] = m.el.querySelector('[data-f=' + k + ']').value; });
