      m.on('click', '[data-hapus]', function (b) { baca(); blok.splice(+b.closest('[data-i]').dataset.i, 1); gambar(); segarkan(); });
      m.on('click', '[data-naik]', function (b) { baca(); var i = +b.closest('[data-i]').dataset.i; if (i > 0) { var x = blok[i]; blok[i] = blok[i - 1]; blok[i - 1] = x; gambar(); segarkan(); } });
      m.on('click', '[data-turun]', function (b) { baca(); var i = +b.closest('[data-i]').dataset.i; if (i < blok.length - 1) { var x = blok[i]; blok[i] = blok[i + 1]; blok[i + 1] = x; gambar(); segarkan(); } });
      m.on('click', '[data-simpan]', function (b) { baca(); var al = m.el.querySelector('[data-alasan]'); if (!al.value.trim()) { al.focus(); al.classList.add('salah'); return UI.toast('Isi catatan perubahan.', 'warn'); } UI.kerja(b, function () { var md = m.el.querySelector('[data-f=mode]').value; return T('tpl.simpan', { jenis: jenis, mode: md, google_docs_id: md === 'GoogleDocs' ? m.el.querySelector('[data-gdocs]').value.trim() : '', blok: blok, hal: hal, alasan: al.value.trim() }); }).then(function (r) { UI.toast(A.API.pesan, 'ok', { aksi: { label: 'Aktifkan v' + r.versi, fn: function () { T('tpl.aktifkan', { id: r.id }).then(function () { UI.toast('Template v' + r.versi + ' aktif.', 'ok'); R.muatUlang(); }).catch(UI.galat); } }, durasi: 8000 }); m.tutup(); R.muatUlang(); }).catch(function () { }); });
